(function () {

    /*jslint node: true, browser: true */
    /*global $tw: false */
    "use strict";

    var Calendar = new Date();

    var createMonth = function (mnth, year, options) {
        var month = [];
        for (var i = 1; i < 1 + daysInMonth(mnth, year); i++) month[i] = createDate(i, mnth, year, options);
        return month;
    }

    function escapeRegExp(string) {
        return string.replace(/[.*+?^${}()|[\]\\]/g, function(match){ return '\\\\' + match; });
    }

    function createDate(i, mnth, year, options) {
        var strong = '', tiddlerDate, format = $tw.wiki.getTiddlerText("$:/config/NewJournal/Title") || "YYYY MM DD";
        var date = (new Date(year, mnth - 1, i));

        var isToday = (year === Calendar.getFullYear() && mnth === (Calendar.getMonth() + 1) && i === Calendar.getDate());
        if (isToday) strong = '!';

        tiddlerDate = $tw.utils.formatDateString(date, format);
        var tiddler = $tw.wiki.getTiddler(tiddlerDate);
        var isUrgent = false;

        // --- TODO DETECTION ---

        // 1. Check Journal Entry Itself (Only if tiddler exists)
        if (tiddler) {
            var itemRegexStr = $tw.wiki.getTiddlerText("$:/config/lithic/Calendar/RegexItems") || "^[ \\t]*(?:[-*]\\s+(?:\\[[ xX]?\\]\\s*)?|\\[[ xX]?\\]\\s+)";
            if (new RegExp(itemRegexStr, "m").test(tiddler.fields.text || "")) {
                isUrgent = true;
            }

            // 2. Check Stream Children (Only if tiddler exists)
            if (!isUrgent && tiddler.fields["stream-list"]) {
                var childList = $tw.utils.parseStringArray(tiddler.fields["stream-list"]);
                if (childList) {
                    for (var c = 0; c < childList.length; c++) {
                        var childTid = $tw.wiki.getTiddler(childList[c]);
                        var itemRegexStr = $tw.wiki.getTiddlerText("$:/config/lithic/Calendar/RegexItems") || "^[ \\t]*(?:[-*]\\s+(?:\\[[ xX]?\\]\\s*)?|\\[[ xX]?\\]\\s+)";
                        if (childTid && new RegExp(itemRegexStr, "m").test(childTid.fields.text || "")) {
                            isUrgent = true;
                            break;
                        }
                    }
                }
            }
        }

        // 3. Check Backlinks (Works even if journal tiddler is missing)
        if (!isUrgent) {
            var backlinks = $tw.wiki.getTiddlerBacklinks(tiddlerDate);
            if (backlinks && backlinks.length > 0) {
                var safeDate = escapeRegExp(tiddlerDate);
                // Look for [ ] or [x] or bare bullets `- ` pointing to the date
                var itemRegexStr = $tw.wiki.getTiddlerText("$:/config/lithic/Calendar/RegexItems") || "^[ \\t]*(?:[-*]\\s+(?:\\[[ xX]?\\]\\s*)?|\\[[ xX]?\\]\\s+)";
                var backlinkRegex = new RegExp(itemRegexStr + ".*\\[\\[" + safeDate + "\\]\\]", "m");

                for (var b = 0; b < backlinks.length; b++) {
                    var blTid = $tw.wiki.getTiddler(backlinks[b]);
                    if (blTid && backlinkRegex.test(blTid.fields.text)) {
                        isUrgent = true;
                        break;
                    }
                }
            }
        }

        // --- RENDER ---

        var label = i;
        if (isUrgent) {
            label = "-" + i + "-";
        }

        // MODIFIED LOGIC:
        // Render the link if the tiddler exists OR if we found urgent items (backlinks)
        var link = '[[' + label + '|' + tiddlerDate + ']]';

        if (tiddler || isUrgent) {
            return centre(strong + link);
        } else {
            // Fallback for missing dates: style as normal text but keep the today indicator
            return centre(strong + '<span class="calendar-date-fallback">' + link + '</span>');
        }
    }

    function daysInMonth(iMonth, iYear) {
        return 32 - new Date(iYear, iMonth - 1, 32).getDate();
    }
    function centre(x) { return ' ' + x + ' '; }
    exports.createMonth = createMonth;
})();"},"$:/macros/buggyj/Calendar/base.js":{"title":"$:/macros/buggyj/Calendar/base.js","module-type":"macro","type":"application/javascript","text":"/*\
title: $:/macros/buggyj/Calendar/base.js
type: application/javascript
module-type: macro

<<diary year month>>
<<diary year>> - year calendar
<<diary>> - this month

Options:$:/macros/diary/options.json
\*/
(function () {

    /*jslint node: true, browser: true */
    /*global $tw: false */
    "use strict";

    exports.name = "calendarbase";

    exports.params = [
        { name: "year" }, { name: "month" }, { name: "opts" }, { name: "offset" }
    ];

    exports.run = function (year, month, opts) {
        if (!opts) opts = "default";
        var options = $tw.wiki.getTiddlerData("$:/config/bj/Calendar.json")[opts] ||
            { lastDayOfWeek: "6", formatter: "", titlebold: "", highlightThisDay: "", highlightThisDate: "" };
        var createMonth;
        try {
            createMonth = require(options.formatter).createMonth;
        } catch (e) {
            createMonth = function (mnth, year) {
                var month = [];
                for (var i = 1; i < 1 + daysInMonth(mnth, year); i++) month[i] = i;
                return month;
            }
        }
        var boldtitle = (options.titlebold == 'yes') ? '!' : '';
        var day_of_week = (function () {
            var days = [];
            for (var i = 0; i < 7; i++) { days[i] = $tw.language.getString("Date/Short/Day/" + i); }
            return days;
        })();
        var month_of_year = (function () {
            var months = [];
            for (var i = 1; i < 13; i++) { months[i] = $tw.language.getString("Date/Long/Month/" + i); }
            return months;
        })();
        var Calendar = new Date();
        var thisyear = Calendar.getFullYear();  //  year (xxxx)
        var thismonth = Calendar.getMonth() + 1;	//  month (0-11)
        var thisday = Calendar.getDay();        //  day (0-6)
        var WEEKFIN = parseInt(options.lastDayOfWeek);
        var MONTHS_IN_YEAR = 12;

        var lf = '\n';
        var cal = '<div>' + lf + lf;
        var ayear = thisyear;

        // Helper to calculate next month for the preview
        function getNext(m, y) {
            var nm = parseInt(m) + 1;
            var ny = parseInt(y);
            if (nm > 12) { nm = 1; ny++; }
            return { m: nm, y: ny };
        }

        if (!!month) {
            // CASE 1: Specific Month Requested
            if (!!year) {
                cal += calendar(month, year, options) + lf;
                var next = getNext(month, year);
                cal += calendar(next.m, next.y, options, true); // Append next 2 weeks
            } else {
                cal += calendar(month, thisyear, options) + lf;
                var next = getNext(month, thisyear);
                cal += calendar(next.m, next.y, options, true); // Append next 2 weeks
            }
        } else {
            if (!!year) {
                // CASE 2: Year View (Single Column Stack)
                ayear = year;
                // MODIFIED: Show 15 months (spill over into next year's Jan/Feb/Mar)
                var tmpI, currentMonth, currentYear;
                // MODIFIED: Show 15 months (spill over into next year's Jan/Feb/Mar)
                for (tmpI = 0; tmpI < 15; tmpI++) {
                    currentMonth = (tmpI % 12) + 1;
                    // Calculate year offset (0 for first 12 months, +1 for months 13-15)
                    currentYear = parseInt(ayear, 10) + Math.floor(tmpI / 12);
                    cal += calendar(currentMonth, currentYear, options) + lf;
                }
            } else {
                // CASE 3: Current Month View (Default)
                var targetMonth = thismonth;
                var targetYear = thisyear;
                var monthOffset = parseInt($tw.wiki.getTiddlerText("$:/state/calendar/monthOffset") || "0", 10);
                if (monthOffset) {
                    targetMonth += monthOffset;
                    while (targetMonth > 12) { targetMonth -= 12; targetYear++; }
                    while (targetMonth < 1) { targetMonth += 12; targetYear--; }
                }
                cal += calendar(targetMonth, targetYear, options) + lf;
                var next = getNext(targetMonth, targetYear);
                cal += calendar(next.m, next.y, options, true); // Append next 2 weeks
            }
        }
        return cal + lf + lf + '</div>';

        // calendar function now accepts previewMode boolean
        function calendar(mnth, year, options, previewMode) {
            var month = createMonth(mnth, year, options);
            var blankdays = (firstDayInMonth(mnth, year) + 13 - WEEKFIN) % 7;
            return titleOfMonth(mnth, year) + createWeekHeading(mnth, year) +
                formatAsMonth(month, blankdays, previewMode, mnth, year, options);
        }

        function getMonthDates(mnth, year) {
            var format = $tw.wiki.getTiddlerText("$:/config/NewJournal/Title") || "YYYY MM DD";
            var dates = [];
            var days = daysInMonth(mnth, year);
            var i, date, tiddlerDate;
            for(i=1; i<=days; i++) {
                date = new Date(year, mnth-1, i);
                tiddlerDate = $tw.utils.formatDateString(date, format);
                dates.push(tiddlerDate);
            }
            return dates;
        }

        function titleOfMonth(mth, year) {
            var dates = getMonthDates(mth, year);
            var tooltipText = "Targeting: " + dates.join(' | ');
            var actionString = "";
            if (dates && dates.length > 0) {
                for (var j = 0; j < dates.length; j++) {
                    if ($tw.wiki.getTiddler(dates[j])) {
                        actionString += '<$action-navigate $to="""' + dates[j] + '""" $scroll="yes"/>';
                    }
                }
            }
            var button = '<$button class="tc-btn-invisible tc-tiddlylink" tooltip="' + tooltipText.replace(/"/g, "'") + '">' + month_of_year[mth] + ' ' + year + actionString + '</$button>';
            return '|calendar-table|k' + lf + '|>|>|>|' + centre(boldtitle + button) + '|<|<|<|<|' + lf;
        }

        function getWeekDates(cellDate, options) {
            var format = $tw.wiki.getTiddlerText("$:/config/NewJournal/Title") || "YYYY MM DD";
            var dates = [];
            var wkstart = (parseInt(options.lastDayOfWeek, 10) + 1) % 7; 
            var day = cellDate.getDay();
            var diff = (day >= wkstart) ? (day - wkstart) : (7 - wkstart + day);
            var startDate = new Date(cellDate.getFullYear(), cellDate.getMonth(), cellDate.getDate() - diff);
            var i, d;

            for(i=0; i<7; i++) {
                d = new Date(startDate.getFullYear(), startDate.getMonth(), startDate.getDate() + i);
                dates.push($tw.utils.formatDateString(d, format));
            }
            return dates;
        }

        function getWeekNumberAndYear(date) {
            var d = new Date(date.getTime());
            var week1;
            d.setHours(0, 0, 0, 0);
            d.setDate(d.getDate() + 3 - (d.getDay() + 6) % 7);
            week1 = new Date(d.getFullYear(), 0, 4);
            var wn = 1 + Math.round(((d.getTime() - week1.getTime()) / 86400000 - 3 + (week1.getDay() + 6) % 7) / 7);
            return { week: wn, year: d.getFullYear() };
        }

        function formatAsMonth(month, blankdays, previewMode, mth, year, options) {
            var theday, blank = ['', '|', '||', '|||', '||||', '|||||', '||||||', '|||||||'];
            var weekCount = 0;
            var cal, i; // moving cal and i to function scope

            function getWeekCell(dayNumber) {
                var cellDate = new Date(year, mth - 1, dayNumber);
                var iso = getWeekNumberAndYear(cellDate);
                var wn = iso.week;
                var isoYear = iso.year;
                var caption = "Week " + ("0"+wn).slice(-2) + ", " + isoYear;
                var targetTitle = "$:/Weekview";

                var tooltipText = "Targeting: " + caption;
                var actionString = '<$action-setfield $tiddler="$:/temp/calendar/refresh" text=<<now "YYYY0MM0DD0hh0mm0ss">> />' +
                                   '<$action-setfield $tiddler="""' + targetTitle + '""" text="""<$macrocall $name="weekview" weeknumber="' + wn + '" year="' + isoYear + '" refresh={{$:/temp/calendar/refresh}}/>""" caption="""' + caption + '""" />' +
                                   '<$action-navigate $to="""' + targetTitle + '""" $scroll="yes"/>';

                var button = '<$button class="tc-btn-invisible tc-tiddlylink" tooltip="' + tooltipText.replace(/"/g, "'") + '">' + ("0"+wn).slice(-2) + actionString + '</$button>';
                return centre(button);
            }

            cal = '|' + getWeekCell(1) + blank[blankdays];

            for (i = 1; i < month.length; i++) {//first '0' month element is not used
                cal += '|' + month[i];
                theday = (i + blankdays - 1) % 7;
                if (theday == 6) {
                    cal += '|' + lf;
                    weekCount++;
                    if (previewMode && weekCount >= 2) return cal;

                    if (i < month.length - 1) {
                        cal += '|' + getWeekCell(i + 1);
                    }
                }
            }
            if (theday !== 6) cal += blank[7 - theday] + lf;//pad out rest of week, if needed
            return cal;
        }
        function createWeekHeading(mnth, year) {
            var daystitle = [], weekdays = day_of_week.slice(0);
            var i;
            var format = $tw.wiki.getTiddlerText("$:/config/NewJournal/Title") || "YYYY MM DD";

            var datesByWeekday = [[], [], [], [], [], [], []]; 
            if (mnth && year) {
                var days = daysInMonth(mnth, year);
                for(var d=1; d<=days; d++) {
                    var dateObj = new Date(year, mnth-1, d);
                    var tiddlerDate = $tw.utils.formatDateString(dateObj, format);
                    datesByWeekday[dateObj.getDay()].push(tiddlerDate);
                }
            }

            if (options.highlightThisDay == 'yes') weekdays[thisday] = '!' + weekdays[thisday];

            for (i = 0; i < weekdays.length; i++) {
                var logicalDay = (i + 1 + WEEKFIN) % 7;
                var label = weekdays[logicalDay];

                if (mnth && year) {
                    var targetDates = datesByWeekday[logicalDay];
                    var actionString = "";
                    if (targetDates && targetDates.length > 0) {
                        for (var j = 0; j < targetDates.length; j++) {
                            if ($tw.wiki.getTiddler(targetDates[j])) {
                                actionString += '<$action-navigate $to="""' + targetDates[j] + '""" $scroll="yes"/>';
                            }
                        }
                    }
                    var tooltipText = "Targeting (" + label + "): " + targetDates.join(' | ');
                    var hc = '<$button class="tc-btn-invisible tc-tiddlylink" tooltip="' + tooltipText.replace(/"/g, "'") + '">' + label + actionString + '</$button>';
                    daystitle[i] = centre(hc);
                } else {
                    daystitle[i] = centre(label);
                }
            }
            return '|!W|' + daystitle.join('|') + '|' + lf;
        }
        function centre(x) { return ' ' + x + ' '; }
        function daysInMonth(iMonth, iYear) {
            return 32 - new Date(iYear, iMonth - 1, 32).getDate();
        }
        function firstDayInMonth(iMonth, iYear) {
            return new Date(iYear, iMonth - 1, 1).getDay();
        }
    }

})();"},"$:/macros/lithic/Calendar/weekview.js":{"title":"$:/macros/lithic/Calendar/weekview.js","type":"application/javascript","module-type":"macro","text":"/*\
title: $:/macros/lithic/Calendar/weekview.js
type: application/javascript
module-type: macro

<<weekview>>
\*/
(function () {

    /*jslint node: true, browser: true */
    /*global $tw: false */
    "use strict";

    exports.name = "weekview";

    exports.params = [
        { name: "weeknumber" },
        { name: "year" },
        { name: "opts" },
        { name: "refresh" }
    ];

    function escapeRegExp(string) {
        return string.replace(/[.*+?^${}()|[\]\\]/g, function(match){ return '\\\\' + match; });
    }

    function getISOWeekInfo(date) {
        var d = new Date(date.getTime());
        d.setHours(0, 0, 0, 0);
        d.setDate(d.getDate() + 3 - (d.getDay() + 6) % 7);
        var week1 = new Date(d.getFullYear(), 0, 4);
        var wn = 1 + Math.round(((d.getTime() - week1.getTime()) / 86400000 - 3 + (week1.getDay() + 6) % 7) / 7);
        return { week: wn, year: d.getFullYear() };
    }

    exports.run = function (weeknumber, year, opts) {
        var options = $tw.wiki.getTiddlerData("$:/config/bj/Calendar.json")["default"] ||
            { lastDayOfWeek: "6" };

        var format = $tw.wiki.getTiddlerText("$:/config/NewJournal/Title") || "YYYY MM DD";

        var baseDate = new Date();
        var currentIso = getISOWeekInfo(baseDate);

        var targetWeek = weeknumber ? parseInt(weeknumber, 10) : currentIso.week;
        var targetYear = year ? parseInt(year, 10) : currentIso.year;

        // Calculate Monday of the target ISO week
        var jan4 = new Date(targetYear, 0, 4);
        var day = jan4.getDay();
        var diffFromMonday = (day === 0 ? 6 : day - 1);
        var firstMonday = new Date(targetYear, 0, 4 - diffFromMonday);
        var targetMonday = new Date(firstMonday.getFullYear(), firstMonday.getMonth(), firstMonday.getDate() + (targetWeek - 1) * 7);

        // Determine start of week based on options.lastDayOfWeek (0=Sun, 1=Mon... 6=Sat)
        // targetMonday is ISO week start (Monday). If user prefers Sunday (lastDayOfWeek=6), adjust.
        var wkstart = (parseInt(options.lastDayOfWeek, 10) + 1) % 7; 
        var mDay = targetMonday.getDay();
        var diff = (mDay >= wkstart) ? (mDay - wkstart) : (7 - wkstart + mDay);
        var startDate = new Date(targetMonday.getFullYear(), targetMonday.getMonth(), targetMonday.getDate() - diff);

        var day_of_week = (function () {
            var days = [];
            for (var i = 0; i < 7; i++) { days[i] = $tw.language.getString("Date/Short/Day/" + i); }
            return days;
        })();

        var month_of_year = (function () {
            var months = [];
            for (var i = 1; i < 13; i++) { months[i] = $tw.language.getString("Date/Long/Month/" + i); }
            return months;
        })();
        var startMonth = month_of_year[startDate.getMonth() + 1];
        var endDate = new Date(startDate.getFullYear(), startDate.getMonth(), startDate.getDate() + 6);
        var endMonth = month_of_year[endDate.getMonth() + 1];
        var monthLabel = startMonth === endMonth ? startMonth : startMonth + " / " + endMonth;

        var html = '<h3>' + monthLabel + ' during Week ' + targetWeek + ' of ' + targetYear + '</h3>\n\n' +
                   '<div class="lithic-weekview-container">\n\n' +
                   '<$multi.column count="7" border="yes" break="yes" gap="2px">\n';

        for(var i=0; i<7; i++) {
            var d = new Date(startDate.getFullYear(), startDate.getMonth(), startDate.getDate() + i);
            var tiddlerDate = $tw.utils.formatDateString(d, format);
            var dayLabel = day_of_week[d.getDay()];
            var isToday = (d.toDateString() === new Date().toDateString());

            var items = [];
            var tiddler = $tw.wiki.getTiddler(tiddlerDate);

            // 1. Check Journal Entry Itself
            if (tiddler) {
                var itemRegexStr = $tw.wiki.getTiddlerText("$:/config/lithic/Calendar/RegexItems") || "^[ \\t]*(?:[-*]\\s+(?:\\[[ xX]?\\]\\s*)?|\\[[ xX]?\\]\\s+)";
                if (new RegExp(itemRegexStr, "m").test(tiddler.fields.text || "")) {
                    items.push(tiddler.fields.title);
                }

                // 2. Check Stream Children
                if (tiddler.fields["stream-list"]) {
                    var childList = $tw.utils.parseStringArray(tiddler.fields["stream-list"]);
                    if (childList) {
                        for (var c = 0; c < childList.length; c++) {
                            var childTid = $tw.wiki.getTiddler(childList[c]);
                            var itemRegexStr = $tw.wiki.getTiddlerText("$:/config/lithic/Calendar/RegexItems") || "^[ \\t]*(?:[-*]\\s+(?:\\[[ xX]?\\]\\s*)?|\\[[ xX]?\\]\\s+)";
                            if (childTid && new RegExp(itemRegexStr, "m").test(childTid.fields.text || "")) {
                                items.push(childTid.fields.title);
                            }
                        }
                    }
                }
            }

            // 3. Check Backlinks
            var backlinks = $tw.wiki.getTiddlerBacklinks(tiddlerDate);
            if (backlinks && backlinks.length > 0) {
                var safeDate = escapeRegExp(tiddlerDate);
                var itemRegexStr = $tw.wiki.getTiddlerText("$:/config/lithic/Calendar/RegexItems") || "^[ \\t]*(?:[-*]\\s+(?:\\[[ xX]?\\]\\s*)?|\\[[ xX]?\\]\\s+)";
                var backlinkRegex = new RegExp(itemRegexStr + ".*\\[\\[" + safeDate + "\\]\\]", "m");

                for (var b = 0; b < backlinks.length; b++) {
                    var blTid = $tw.wiki.getTiddler(backlinks[b]);
                    if (blTid && backlinkRegex.test(blTid.fields.text)) {
                        if (items.indexOf(blTid.fields.title) === -1) {
                            items.push(blTid.fields.title);
                        }
                    }
                }
            }

            // 4. Check Recurring Tiddlers (tagged with full weekday name, e.g. "Monday")
            var fullDayNames = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
            var recurring = $tw.wiki.filterTiddlers("[tag[" + fullDayNames[d.getDay()] + "]!is[system]]");
            for (var r = 0; r < recurring.length; r++) {
                if (items.indexOf(recurring[r]) === -1) {
                    items.push(recurring[r]);
                }
            }

            // Sort items numerically/alphabetically (lowest to highest)
            items.sort();

            // Add column break if not the first column
            if (i > 0) {
                html += '<hr><hr>\n';
            }

            // Header: Day + Date link
            var headerText = dayLabel + ' ' + d.getDate();
            var headerClass = isToday ? "lithic-weekview-header lithic-weekview-today" : "lithic-weekview-header";
            html += '<div class="' + headerClass + '"><$link to="""' + tiddlerDate + '""">' + headerText + '</$link></div>\n';

            // Transclude items
            html += '<div class="lithic-weekview-items">\n';
            if (items.length === 0) {
                html += '<div style="text-align:center; color:<<colour muted-foreground>>; font-style:italic; font-size:0.85em; margin-top:5px;">*Free*</div>\n';
            } else {
                for (var j = 0; j < items.length; j++) {
                    html += '{{' + items[j] + '||$:/plugins/sq/streams/templates/stream-row-body}}\n';
                }
            }
            html += '</div>\n';
        }

        html += '</$multi.column>\n</div>';

        return html;
    }

})();"},"$:/plugins/bj/calendar/sidbar":{"title":"$:/plugins/bj/calendar/sidbar","caption":"Calendar","tags":"$:/tags/SideBar","type":"text/vnd.tiddlywiki","text":"<$reveal state="$:/temp/plugins/bj/Calendar" text="Year" type="nomatch">
<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
  <$button set="$:/temp/plugins/bj/Calendar" setTo="Year">Year</$button>

  <div style="display: flex; align-items: center; gap: 16px;">
      <$button class="tc-btn-invisible" tooltip="Previous Month">
          <$action-setfield $tiddler="$:/state/calendar/monthOffset" text={{{ [[$:/state/calendar/monthOffset]get[text]else[0]subtract[1]] }}} />
          &lt; prev
      </$button>
      <$let currentOffset={{{ [[$:/state/calendar/monthOffset]get[text]else[0]] }}}>
      <$let btnClass={{{ [<currentOffset>match[0]then[tc-btn-invisible lithic-calendar-now-active]else[tc-btn-invisible]] }}}>
      <$button class=<<btnClass>> tooltip="Current Month / Refresh">
          <$action-setfield $tiddler="$:/state/calendar/monthOffset" text="0" />
          <$action-setfield $tiddler="$:/temp/calendar/refresh" text=<<now "YYYY0MM0DD0hh0mm0ss">> />
          now
